// Text layout without a font engine: word wrap by an estimated glyph width.
// Every adapter (Herdr, SVG, a browser later) draws the same lines, so labels
// wrap identically everywhere and the file stays the single source of truth.

// Glyph advances / font size for printable ASCII (32-126), in the fonts the pane draws with
// (adapters/herdr face()): SF Pro as the pane spaces it, and Chalkboard SE, the first installed
// hand font. Generated by scripts/glyph-widths.mjs (measured 2026-11-08; the live pane matched
// within 0.5% on a test sentence). Mono is 0.6 for every common terminal font.
const GLYPH = {
  sans: [0.262, 0.292, 0.458, 0.61, 0.61, 0.906, 0.692, 0.277, 0.362, 0.362, 0.452, 0.61, 0.277, 0.452, 0.277, 0.285, 0.61, 0.444, 0.584, 0.607, 0.624, 0.599, 0.617, 0.55, 0.619, 0.617, 0.277, 0.277, 0.61, 0.61, 0.61, 0.493, 0.898, 0.654, 0.638, 0.696, 0.707, 0.576, 0.553, 0.727, 0.723, 0.248, 0.519, 0.639, 0.548, 0.854, 0.723, 0.752, 0.616, 0.752, 0.634, 0.618, 0.614, 0.718, 0.654, 0.948, 0.659, 0.636, 0.642, 0.362, 0.285, 0.362, 0.61, 0.564, 0.48, 0.532, 0.595, 0.54, 0.595, 0.552, 0.342, 0.59, 0.569, 0.228, 0.227, 0.523, 0.233, 0.851, 0.564, 0.571, 0.591, 0.59, 0.361, 0.504, 0.344, 0.564, 0.522, 0.755, 0.505, 0.523, 0.52, 0.362, 0.239, 0.362, 0.61],
  hand: [0.382, 0.255, 0.453, 0.798, 0.579, 0.811, 0.708, 0.193, 0.315, 0.315, 0.498, 0.539, 0.255, 0.476, 0.295, 0.545, 0.569, 0.569, 0.569, 0.569, 0.569, 0.569, 0.569, 0.569, 0.569, 0.569, 0.285, 0.362, 0.425, 0.487, 0.442, 0.45, 0.817, 0.645, 0.57, 0.587, 0.636, 0.547, 0.501, 0.664, 0.622, 0.443, 0.55, 0.585, 0.518, 0.828, 0.656, 0.726, 0.579, 0.76, 0.624, 0.588, 0.569, 0.657, 0.646, 0.988, 0.655, 0.587, 0.656, 0.31, 0.519, 0.298, 0.483, 0.635, 0.295, 0.536, 0.559, 0.493, 0.514, 0.526, 0.432, 0.527, 0.544, 0.25, 0.388, 0.528, 0.301, 0.737, 0.51, 0.487, 0.528, 0.516, 0.438, 0.431, 0.457, 0.528, 0.465, 0.72, 0.557, 0.536, 0.535, 0.344, 0.252, 0.351, 0.639],
};
const MONO = 0.6, OTHER = 0.6;   // OTHER: a char outside the tables (accents, symbols)
// East Asian wide chars and emoji take about a full em.
const wide = c => c >= 0x1100 && (c <= 0x115f || (c >= 0x2e80 && c <= 0xa4cf) || (c >= 0xac00 && c <= 0xd7a3) ||
  (c >= 0xf900 && c <= 0xfaff) || (c >= 0xfe30 && c <= 0xfe4f) || (c >= 0xff00 && c <= 0xff60) || (c >= 0xffe0 && c <= 0xffe6) || c >= 0x1f300);

// Excalidraw fontFamily → font class (as core/style.js fontClass; kept here so text.js imports nothing).
export const fontKind = ff => (ff === 1 || ff === 5 || ff === 8 ? "hand" : ff === 3 ? "mono" : "sans");

// Width of one line in scene px at this size, for a font class ("sans" | "hand" | "mono").
export function lineWidth(line, fontSize, kind = "sans") {
  const table = GLYPH[kind];
  let w = 0;
  for (const ch of String(line ?? "")) {
    const c = ch.codePointAt(0);
    w += wide(c) ? (kind === "mono" ? 2 * MONO : 1) : !table ? MONO : (table[c - 32] ?? OTHER);
  }
  return w * fontSize;
}
// The same, for an Excalidraw fontFamily.
export const textWidth = (line, fontSize, fontFamily = 2) => lineWidth(line, fontSize, fontKind(fontFamily));
export const LABEL_PAD = 8;        // space between a label and its shape's edge, scene px

// How much of a shape's width a centered label may use (Excalidraw's factors):
// a diamond's middle is half its width; an ellipse's inscribed box is w/√2.
export function labelWidthFactor(type) {
  if (type === "diamond") return 0.5;
  if (type === "ellipse") return Math.SQRT1_2;
  return 1;
}

// Split text into lines no wider than maxW (scene px) at this font size and family.
// Explicit newlines are kept. A word wider than a line breaks at its seams first (camelCase humps,
// before an opening bracket, after _ - . / : , and closing brackets): "EvaluateNdc" + "FraudBlock)".
// A seam piece still too wide breaks between letters, in even pieces ("signa" + "ture", not "signatu" + "re").
export function wrapLines(text, maxW, fontSize, fontFamily = 2) {
  if (!(fontSize > 0) || !Number.isFinite(fontSize)) return String(text ?? "").split("\n");   // a broken board: don't wrap
  const W = t => textWidth(t, fontSize, fontFamily);
  if (!(maxW > 0)) maxW = W("M");
  const out = [];
  for (const para of String(text ?? "").split("\n")) {
    if (!para) { out.push(""); continue; }
    let line = "";
    for (const word of para.split(/ +/)) {
      let w = word;
      if (W(w) > maxW) {
        if (line) { out.push(line); line = ""; }
        const pieces = breakWord(w, maxW, W);
        out.push(...pieces.slice(0, -1)); w = pieces[pieces.length - 1];
      }
      if (!line) line = w;
      else if (W(line + " " + w) <= maxW) line += " " + w;
      else { out.push(line); line = w; }
    }
    out.push(line);
  }
  return out;
}

// Where a word may break without reading as a typo: before a camelCase hump (aB, a1B, HTTPServer → HTTP|Server)
// or an opening bracket, after _ - . / : , ; = and closing brackets.
function seams(word) {
  const atoms = []; let cur = "";
  const ch = [...word], up = c => c >= "A" && c <= "Z", low = c => (c >= "a" && c <= "z") || (c >= "0" && c <= "9");
  for (let i = 0; i < ch.length; i++) {
    const c = ch[i], prev = ch[i - 1], next = ch[i + 1];
    const before = cur && (("([{<".includes(c)) || (up(c) && prev && (low(prev) || (up(prev) && next && low(next)))));
    if (before) { atoms.push(cur); cur = ""; }
    cur += c;
    if ("_-./:,;=)]}>".includes(c) && i < ch.length - 1) { atoms.push(cur); cur = ""; }
  }
  if (cur) atoms.push(cur);
  return atoms;
}

// A word wider than maxW as lines no wider than maxW (while there's more than one char to a line).
function breakWord(word, maxW, W) {
  const out = []; let cur = "";
  for (const atom of seams(word)) {
    if (W(cur + atom) <= maxW) { cur += atom; continue; }
    if (cur) { out.push(cur); cur = ""; }
    if (W(atom) <= maxW) { cur = atom; continue; }
    const parts = letters(atom, maxW, W);
    out.push(...parts.slice(0, -1)); cur = parts[parts.length - 1];
  }
  if (cur) out.push(cur);
  return out;
}

// Letters in as few lines as fit, then evened out so the last isn't a stub.
function letters(s, maxW, W) {
  const ch = [...s], greedy = [];
  for (let i = 0; i < ch.length;) {   // at least one char per line, so it ends
    let n = 1; while (i + n < ch.length && W(ch.slice(i, i + n + 1).join("")) <= maxW) n++;
    greedy.push(ch.slice(i, i + n).join("")); i += n;
  }
  if (greedy.length < 2) return greedy;
  const per = Math.ceil(ch.length / greedy.length), even = [];
  for (let i = 0; i < ch.length; i += per) even.push(ch.slice(i, i + per).join(""));
  return even.length === greedy.length && even.every(p => W(p) <= maxW) ? even : greedy;
}

// The lines a shape's label shows at the shape's current width.
export function labelLines(label, host) {
  const usable = Math.max(label.fontSize, Math.abs(host.width) * labelWidthFactor(host.type) - LABEL_PAD * 2);
  return wrapLines(label.text, usable, label.fontSize, label.fontFamily);
}

// The width a shape needs so no word of its label has to break or spill: the widest word
// (or line, when nothing can wrap) plus padding, over the share of the width a label may use.
// A little slack, since widths are estimates. Wider shapes keep their width.
export function labelHostWidth(label, type = "rectangle") {
  if (!label?.text || !(label.fontSize > 0)) return 0;
  const words = String(label.text).split(/[ \n]+/).filter(Boolean);
  const widest = Math.max(0, ...words.map(w => textWidth(w, label.fontSize, label.fontFamily)));
  return Math.ceil((widest + LABEL_PAD * 2) / labelWidthFactor(type) + 4);
}

// The height a shape needs so its wrapped label fits inside.
export function labelHostHeight(label, host) {
  const lines = labelLines(label, host).length;
  const textH = lines * label.fontSize * (label.lineHeight ?? 1.25);
  const f = host.type === "diamond" ? 0.5 : host.type === "ellipse" ? Math.SQRT1_2 : 1;
  return textH / f + LABEL_PAD * 2;
}
